contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Roulette c;

    function setUp() public {
        vm.deal(address(this), 10 ether);
        c = new Roulette{value: 10 ether}();
    }

    function _run(uint256 x) internal {
        vm.assume(x <= 1e30);
        uint256 t1;
        try c.pastBlockTime() returns (uint256 __r) { t1 = __r; } catch { return; }
        uint256 t2;
        try c.pastBlockTime() returns (uint256 __r) { t2 = __r; } catch { return; }
        uint b1 = address(c).balance;
        uint256 t3;
        try c.pastBlockTime() returns (uint256 __r) { t3 = __r; } catch { return; }
        assertTrue(t1 == t2 && t2 == t3 && address(c).balance == b1);
    }

    function testFuzz_run(uint256 x) public {
